SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'data_quality_items', 'Datenqualitätsanforderungen §5.2.4.2 a) – j) (Prüfliste, Mehrfachauswahl)', 'json', NULL, false, '§5.2.4.2', 'Plan 3: Mehrfachauswahl über die zehn gedruckten Datenqualitätspunkte a) – j) (S5_2_4_2_DQ); das Einzelfeld data_quality_requirements bleibt (iso14046-D-24); data_quality_complete_code ist STAGED (iso14046-F-2 — seit Plan 3 Welle A erreicht contains() den Materialisierer; der Block bleibt bis zur Ratifizierung STAGED).', 'imported_unverified', 'Los requisitos para la calidad de los datos deberían tratar lo siguiente: — a) cobertura relacionada con el tiempo: antigüedad de los datos y período de tiempo mínimo en el que se deberían recopilar los datos;', 'select_many', '{"title":"Anforderungen an die Datenqualität (§5.2.4.2 a) – j))","subtitle":"„Los requisitos para la calidad de los datos deberían tratar lo siguiente:“ — ankreuzen, welche Punkte die Datenqualitätsanforderungen behandeln","note":"Los requisitos para la calidad de los datos deberían tratar lo siguiente: Das Einzelfeld data_quality_requirements (ein Boolean für alle zehn) bleibt bis zur Ratifizierung (iso14046-D-24); REQ-06 liest heute den Boolean — ein Vollständigkeits-Code über die Checkliste ist noch nicht codiert — Entscheidung auf dem Sign-off-Bogen (iso14046-F-2). Modalverb „deberían“ (sollten) — Anhaltswert, keine Pflichtliste.","groups":[{"label":"§5.2.4.2 a) – j)","options":["a) cobertura relacionada con el tiempo: antigüedad de los datos y período de tiempo mínimo en el que se deberían recopilar los datos;","b) cobertura geográfica: área geográfica donde se deberían recopilar los datos de los procesos unitarios para satisfacer el objetivo del estudio;","c) cobertura tecnológica: tecnología específica o mezcla de tecnologías;","d) precisión: medida de la variabilidad de los valores de los datos para cada dato expresado (por ejemplo: varianza);","e) integridad: porcentaje de datos que se han medido o estimado;","f) representatividad: evaluación cualitativa del grado en el cual el conjunto de datos reflejan la verdadera población de interés (por ejemplo: cobertura geográfica, período de tiempo y cobertura tecnológica);","g) coherencia: evaluación cualitativa de si la metodología del estudio se aplica de manera uniforme a los distintos componentes del análisis;","h) reproducibilidad: evaluación cualitativa de la extensión en la cual la información sobre la metodología y los valores de los datos podrían permitir a un profesional independiente reproducir los resultados que han sido informados;","i) fuentes de los datos, incluyendo los modelos cuando se utilicen (incluyendo documentación sobre las suposiciones del modelo; variación del modelo y exactitud);","j) incertidumbre de la información (por ejemplo: datos, modelos y suposiciones)."]}]}'::jsonb, NULL, NULL, '[{"value":"a) cobertura relacionada con el tiempo: antigüedad de los datos y período de tiempo mínimo en el que se deberían recopilar los datos;","label_de":"a) cobertura relacionada con el tiempo: antigüedad de los datos y período de tiempo mínimo en el que se deberían recopilar los datos;","order_index":0},{"value":"b) cobertura geográfica: área geográfica donde se deberían recopilar los datos de los procesos unitarios para satisfacer el objetivo del estudio;","label_de":"b) cobertura geográfica: área geográfica donde se deberían recopilar los datos de los procesos unitarios para satisfacer el objetivo del estudio;","order_index":1},{"value":"c) cobertura tecnológica: tecnología específica o mezcla de tecnologías;","label_de":"c) cobertura tecnológica: tecnología específica o mezcla de tecnologías;","order_index":2},{"value":"d) precisión: medida de la variabilidad de los valores de los datos para cada dato expresado (por ejemplo: varianza);","label_de":"d) precisión: medida de la variabilidad de los valores de los datos para cada dato expresado (por ejemplo: varianza);","order_index":3},{"value":"e) integridad: porcentaje de datos que se han medido o estimado;","label_de":"e) integridad: porcentaje de datos que se han medido o estimado;","order_index":4},{"value":"f) representatividad: evaluación cualitativa del grado en el cual el conjunto de datos reflejan la verdadera población de interés (por ejemplo: cobertura geográfica, período de tiempo y cobertura tecnológica);","label_de":"f) representatividad: evaluación cualitativa del grado en el cual el conjunto de datos reflejan la verdadera población de interés (por ejemplo: cobertura geográfica, período de tiempo y cobertura tecnológica);","order_index":5},{"value":"g) coherencia: evaluación cualitativa de si la metodología del estudio se aplica de manera uniforme a los distintos componentes del análisis;","label_de":"g) coherencia: evaluación cualitativa de si la metodología del estudio se aplica de manera uniforme a los distintos componentes del análisis;","order_index":6},{"value":"h) reproducibilidad: evaluación cualitativa de la extensión en la cual la información sobre la metodología y los valores de los datos podrían permitir a un profesional independiente reproducir los resultados que han sido informados;","label_de":"h) reproducibilidad: evaluación cualitativa de la extensión en la cual la información sobre la metodología y los valores de los datos podrían permitir a un profesional independiente reproducir los resultados que han sido informados;","order_index":7},{"value":"i) fuentes de los datos, incluyendo los modelos cuando se utilicen (incluyendo documentación sobre las suposiciones del modelo; variación del modelo y exactitud);","label_de":"i) fuentes de los datos, incluyendo los modelos cuando se utilicen (incluyendo documentación sobre las suposiciones del modelo; variación del modelo y exactitud);","order_index":8},{"value":"j) incertidumbre de la información (por ejemplo: datos, modelos y suposiciones).","label_de":"j) incertidumbre de la información (por ejemplo: datos, modelos y suposiciones).","order_index":9}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
