SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'elementary_flows', 'Elementare Wasserflüsse (je Prozesseinheit × Fluss: Eingang/Ausgang, Menge, Ressourcentyp, Qualität, Nutzungsform, Ort, Zeit, Emissionen)', 'json', NULL, false, '§5.3.2 a)–g)', 'Plan 3: Zeilen je Prozesseinheit × elementarem Wasserfluss mit den gedruckten Angaben a) – g) von 5.3.2 („El inventario de la huella de agua debe incluir entradas y salidas para cada proceso unitario“); Eingang/Ausgang als Diskriminator (Emissionen nur bei Ausgängen); Σ Eingänge → water_input_total (ISO-14046-03-D1), Σ Ausgänge → water_output_total (-D2), Bilanzdifferenz → water_balance_diff (-D3), Zeilenzahl → elementary_flow_count (-D4), Σ Eingänge je Wasserressourcentyp → water_input_<typ> (-D5 … -D10). Die Einzelskalare dieses Arbeitsblatts und die sechs Rahmen-Textfelder auf -02 bleiben (iso14046-D-1 … D-14).', 'imported_unverified', 'El inventario de la huella de agua debe incluir entradas y salidas para cada proceso unitario que forme parte del sistema en estudio. Cualquier discrepancia en el balance del inventario debe explicarse. — En general, la información de cada flujo elemental, donde sea pertinente debería incluir:', 'register', '{"title":"Elementare Wasserflüsse (flujos elementales, §5.3.2)","subtitle":"§5.3.2 — je Prozesseinheit × Fluss eine Zeile mit den Angaben a) – g); Eingänge und Ausgänge getrennt","add_label":"+ Fluss","placement":"section","columns":[{"key":"unit_process","label":"Prozesseinheit","type":"text","required":true,"aria_label":"Prozesseinheit (proceso unitario, §3.5.6)"},{"key":"direction","label":"Eingang / Ausgang","type":"enum","options":["input","output"],"option_labels":{"input":"Eingang (entrada de agua)","output":"Ausgang (salida de agua)"},"required":true,"discriminator":true,"aria_label":"Eingang oder Ausgang (§5.3.2 a)"},{"key":"quantity_m3","label":"Menge","type":"number","unit":"m³","required":true,"min":0,"aria_label":"Menge des Wasserflusses in m³ (§5.3.2 a)"},{"key":"resource_type","label":"Wasserressourcentyp","type":"enum","options":["rainwater","surface_water","seawater","brackish_water","groundwater","fossil_water"],"option_labels":{"rainwater":"Regenwasser","surface_water":"Oberflächenwasser","seawater":"Meerwasser","brackish_water":"Brackwasser","groundwater":"Grundwasser","fossil_water":"Fossiles Wasser"},"required":true,"aria_label":"Wasserressourcentyp (§5.3.2 b)"},{"key":"quality","label":"Qualitätsparameter","type":"text","aria_label":"Qualitätsparameter und/oder -merkmale des Wassers (§5.3.2 c)"},{"key":"form_of_use","label":"Form der Wassernutzung","type":"enum","options":["evaporation","transpiration","product_integration","release_other_watershed_or_sea","displacement_between_resources","instream_use","other"],"option_labels":{"evaporation":"Verdunstung","transpiration":"Transpiration","product_integration":"Integration in das Produkt","release_other_watershed_or_sea":"Freisetzung in andere Wasserscheide/ins Meer","displacement_between_resources":"Verlagerung zwischen Wasserressourcentypen","instream_use":"Nutzung im Gewässer","other":"Andere"},"aria_label":"Form der Wassernutzung (§5.3.2 d)"},{"key":"location","label":"Geografischer Ort","type":"text","aria_label":"Geografischer Ort der Wassernutzung (§5.3.2 e)"},{"key":"temporal","label":"Zeitliche Aspekte","type":"text","aria_label":"Zeitliche Aspekte der Wassernutzung (§5.3.2 f)"},{"key":"releases","label":"Emissionen / Einleitungen","type":"text","visible_when":"direction == ''output''","aria_label":"Emissionen in die Luft oder Einleitungen in Wasser und Boden mit Wasserqualitätswirkung (§5.3.2 g, nur Ausgänge)"}],"footer":["water_input_total","water_output_total","water_balance_diff","elementary_flow_count"],"note":"El inventario de la huella de agua debe incluir entradas y salidas para cada proceso unitario que forme parte del sistema en estudio. Cualquier discrepancia en el balance del inventario debe explicarse. En general, la información de cada flujo elemental, donde sea pertinente debería incluir: Je Prozesseinheit × Fluss eine Zeile (Eingang oder Ausgang); die Spalten sind die gedruckten Angaben a) – g) von 5.3.2 und Zwillinge der Einzelfelder elementary_flow_quantity / flow_water_resource_type / flow_quality_parameters / flow_form_of_use / flow_geographic_location / flow_temporal_aspects / flow_releases_to_environment (dieses Arbeitsblatt) sowie der sechs Rahmen-Textfelder water_quantities / water_resource_types / water_quality_data / forms_of_water_use / water_use_locations / temporal_aspects auf ISO-14046-02 — die Einzelfelder bleiben bis zur Ratifizierung (iso14046-D-1 … D-14). Einleitungen/Emissionen (g) nur bei Ausgängen. Summen: Eingänge / Ausgänge / Bilanzdifferenz (ISO-14046-03-D1 … D3, 5.3.2 „Cualquier discrepancia en el balance del inventario debe explicarse“) und je Wasserressourcentyp (D5 … D10); keine Aggregation über Typ / Qualität / Form / Ort / Zeitraum in der Inventarphase (L675) — die Zeilen bleiben getrennt."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'elementary_flows') AND w.code = 'ISO-14046-03' AND s.code = 'ISO-14046';
