INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'impact_categories_14046', 'Wirkungskategorien (je Kategorie: Indikator, Einheit, Charakterisierungsmodell, Indikatorergebnis)', 'json', NULL, false, '§5.4.2, §5.4.7', 'Plan 3: Zeilen je Wirkungskategorie („El indicador de categoría o los indicadores de categoría, y el método o métodos … se deben seleccionar“; das Profil „está hecho con varios resultados de indicadores de categorías de impacto“); das Ergebnis je Kategorie ist typisiert (die Summe nach Kategoriename ist ohne gruppiertes Aggregat nicht ausdrückbar — iso14046-F-1); die Einzelfelder bleiben (iso14046-D-15 … D-18, D-26).', 'imported_unverified', 'Los impactos relacionados con el agua están asociados con numerosos mecanismos ambientales y por lo tanto numerosos indicadores de categoría son posibles. El indicador de categoría o los indicadores de categoría, y el método o métodos de evaluación del impacto de la huella de agua se deben seleccionar con base en los objetivos y el alcance del estudio. El método o los métodos aplicados en la evaluación del impacto de la huella de agua deben describirse claramente y documentarse. La descripción debe incluir una descripción de los mecanismos ambientales que son considerados por el método o métodos de evaluación del impacto de la huella de agua. — Un perfil de la huella de agua considera un rango de impactos ambientales potenciales asociados con el agua. Un perfil de la huella de agua está hecho con varios resultados de indicadores de categorías de impacto, que se calculan a partir de varias categorías de impacto.', 'register', '{"title":"Wirkungskategorien und Kategorieindikatoren (§5.4.2)","subtitle":"§5.4.2 — je Wirkungskategorie eine Zeile: Indikator, Charakterisierungsmodell, Indikatorergebnis; das Wasser-Fußabdruck-Profil ist die Menge dieser Zeilen (§3.3.13 / §5.4.7)","add_label":"+ Wirkungskategorie","placement":"section","columns":[{"key":"category","label":"Wirkungskategorie","type":"text","required":true,"aria_label":"Wirkungskategorie (categoría de impacto, §3.3.11)"},{"key":"indicator_name","label":"Kategorieindikator","type":"text","aria_label":"Name des Kategorieindikators (§5.4.2 „debe ser lo suficientemente explícito“)"},{"key":"indicator_unit","label":"Einheit des Indikators","type":"text","aria_label":"Gemeinsame Einheit des Kategorieindikators (§3.3.14)"},{"key":"model","label":"Charakterisierungsmodell","type":"text","aria_label":"Charakterisierungsmodell / -methode (§5.4.4.1)"},{"key":"result","label":"Indikatorergebnis","type":"number","aria_label":"Kategorieindikatorergebnis (Σ Beiträge dieser Kategorie aus lci_cf_rows — von Hand übernommen, iso14046-F-1)"}],"note":"Los impactos relacionados con el agua están asociados con numerosos mecanismos ambientales y por lo tanto numerosos indicadores de categoría son posibles. El indicador de categoría o los indicadores de categoría, y el método o métodos de evaluación del impacto de la huella de agua se deben seleccionar con base en los objetivos y el alcance del estudio. El método o los métodos aplicados en la evaluación del impacto de la huella de agua deben describirse claramente y documentarse. La descripción debe incluir una descripción de los mecanismos ambientales que son considerados por el método o métodos de evaluación del impacto de la huella de agua. Un perfil de la huella de agua considera un rango de impactos ambientales potenciales asociados con el agua. Un perfil de la huella de agua está hecho con varios resultados de indicadores de categorías de impacto, que se calculan a partir de varias categorías de impacto. Je Kategorie eine Zeile (Zwillinge der Einzelfelder impact_categories / category_indicators / characterization_model / category_indicator_result, iso14046-D-15 … D-18; das Profil water_footprint_profile ist die Zeilenmenge, iso14046-D-26). Das Indikatorergebnis je Kategorie ist die Summe der Beiträge dieser Kategorie im Register lci_cf_rows — eine Summe nach frei eingetippter Kategorie ist im Rechenwerk nicht ausdrückbar (kein gruppiertes Aggregat, iso14046-F-1): der Wert wird aus den Zeilen von lci_cf_rows übernommen; die Gesamtsumme aller Beiträge liefert category_indicator_total."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'impact_categories_14046') AND w.code = 'ISO-14046-04' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'lci_cf_rows', 'Sachbilanzergebnis × Charakterisierungsfaktor je Wirkungskategorie (Klassifizierung und Charakterisierung)', 'json', NULL, false, '§5.4.3, §5.4.4.1, §3.3.14', 'Plan 3: Zeilen je zugeordnetem Sachbilanzergebnis (Kategorie, Fluss, Wert, Charakterisierungsfaktor) mit dem Beitrag lci_value × cf als Zeilenwert (die gedruckte Definition 3.3.14: „Factor … que se aplica para convertir el resultado del análisis del inventario del ciclo de vida asignado a la unidad común del indicador de categoría“); Gesamtsumme → category_indicator_total (ISO-14046-04-D1). Prod EQ-01 (category_indicator_result = SUM(lci_result * characterization_factor) über die Einzelfelder) bleibt; EQ-01 auf die Zeilen ist STAGED (iso14046-R-1); die Einzelfelder bleiben (iso14046-D-19 / D-20).', 'imported_unverified', '14.Factor de caracterización. Factor que surge de un modelo de caracterización que se aplica para convertir el resultado del análisis del inventario del ciclo de vida (3.3.6) asignado a la unidad común del indicador de categoría (3.3.12). — Si el cálculo de la huella de agua se basa en categorías de impacto diferentes, los resultados del inventario del ciclo de vida deben asignarse a éstas categorías de impacto diferentes.', 'register', '{"title":"Klassifizierung und Charakterisierung: Sachbilanzergebnis × Charakterisierungsfaktor (§5.4.3 / §5.4.4)","subtitle":"§5.4.4.1 — je zugeordnetem Sachbilanzergebnis eine Zeile: Wirkungskategorie, Fluss, Sachbilanzwert, Charakterisierungsfaktor → Beitrag (EQ-01 je Zeile)","add_label":"+ Sachbilanzergebnis","placement":"section","columns":[{"key":"category","label":"Wirkungskategorie","type":"text","required":true,"aria_label":"Wirkungskategorie, der das Sachbilanzergebnis zugeordnet ist (§5.4.3)"},{"key":"flow","label":"Elementarfluss / Stoff","type":"text","aria_label":"Zugeordneter Elementarfluss oder Stoff (§5.4.3)"},{"key":"lci_value","label":"Sachbilanzergebnis","type":"number","required":true,"aria_label":"Zugeordnetes Sachbilanzergebnis (resultado del análisis del inventario, §3.3.14)"},{"key":"cf","label":"Charakterisierungsfaktor","type":"number","required":true,"aria_label":"Charakterisierungsfaktor (factor de caracterización, §3.3.14)"},{"key":"contribution","label":"Beitrag zum Indikator","type":"derived","expr":"lci_value * cf"}],"footer":["category_indicator_total"],"note":"14.Factor de caracterización. Factor que surge de un modelo de caracterización que se aplica para convertir el resultado del análisis del inventario del ciclo de vida (3.3.6) asignado a la unidad común del indicador de categoría (3.3.12). Si el cálculo de la huella de agua se basa en categorías de impacto diferentes, los resultados del inventario del ciclo de vida deben asignarse a éstas categorías de impacto diferentes. Je zugeordnetem Sachbilanzergebnis eine Zeile; der Beitrag ist Sachbilanzergebnis × Charakterisierungsfaktor (die gedruckte Definition des Charakterisierungsfaktors; prod EQ-01 auf den Einzelfeldern lci_result / characterization_factor bleibt unverändert — iso14046-D-19 / D-20 / R-1). Die Gesamtsumme aller Beiträge ist category_indicator_total (ISO-14046-04-D1); die Summe je Kategorie wird von Hand in impact_categories_14046.result übernommen (iso14046-F-1)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'lci_cf_rows') AND w.code = 'ISO-14046-04' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'category_indicator_total', 'Σ Beiträge aller Sachbilanzergebnisse (aus lci_cf_rows)', 'number', NULL, false, '§5.4.4.1', 'Plan 3: Ausgabe der Gleichung ISO-14046-04-D1 (sum_rows über lci_cf_rows, contribution) — die Gesamtsumme aller Beiträge; sie ist NICHT das Indikatorergebnis einer einzelnen Kategorie (Summe je Kategorie: iso14046-F-1); Zwilling des Einzelfelds category_indicator_result (prod EQ-01, iso14046-D-18); Vererbung nach -05 / -06 STAGED (iso14046-C-1).', 'imported_unverified', '14.Factor de caracterización. Factor que surge de un modelo de caracterización que se aplica para convertir el resultado del análisis del inventario del ciclo de vida (3.3.6) asignado a la unidad común del indicador de categoría (3.3.12).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'category_indicator_total') AND w.code = 'ISO-14046-04' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'H'), 'weighting_report_note', 'Gewichtung: Durchführung und Bericht nach ISO 14044 (§5.4.7)', 'text', NULL, false, '§5.4.7, §5.4.1', 'Plan 3: die im Brief genannte, in prod nicht vorhandene Notiz (iso14046-O-1) — wie die Gewichtung nach ISO 14044 durchgeführt und berichtet wird („Si se aplica la ponderación, esta se debe de realizar e informar de acuerdo con la Norma ISO 14044.“); nur sichtbar bei weighting_applied == true; das gedruckte Verbot der gewichteten Ergebnisse als Grundlage einer öffentlichen vergleichenden Aussage (L846) ist als Gate STAGED (iso14046-G-8).', 'imported_unverified', 'El perfil de la huella de agua se puede agregar como un solo parámetro. Si se aplica la ponderación, esta se debe de realizar e informar de acuerdo con la Norma ISO 14044. — Si se aplica la ponderación, los resultados no deben utilizarse como base de una aseveración comparativa prevista para su divulgación al público.', 'scalar', NULL, NULL, 'weighting_applied == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'weighting_report_note') AND w.code = 'ISO-14046-04' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'significant_issues_14046', 'Signifikante Themen (je Thema: Bezeichnung, Beitrag %, Umweltmechanismus)', 'json', NULL, false, '§5.5 a)', 'Plan 3: Zeilen je signifikantem Thema („identificación de las cuestiones significativas … procesos con una contribución significativa … mecanismos ambientales principalmente afectados, flujos elementales que tienen la mayor contribución“); Anzahl → significant_issues_count (ISO-14046-05-D1); das Textfeld significant_issues bleibt (iso14046-D-21); REQ-16 liest den Text — Umstellung STAGED (iso14046-G-11).', 'imported_unverified', 'a) identificación de las cuestiones significativas basadas en los resultados de la evaluación de la huella de agua por ejemplo: procesos con una contribución significativa al cálculo de las huellas del agua, mecanismos ambientales principalmente afectados, flujos elementales que tienen la mayor contribución a los resultados de la evaluación de la huella de agua;', 'register', '{"title":"Signifikante Themen (cuestiones significativas, §5.5 a))","subtitle":"§5.5 a) — je signifikantem Thema eine Zeile: Prozess, Umweltmechanismus oder Elementarfluss mit dem größten Beitrag","add_label":"+ Thema","placement":"section","columns":[{"key":"issue","label":"Thema","type":"text","required":true,"aria_label":"Signifikantes Thema (Prozess / Mechanismus / Elementarfluss, §5.5 a)"},{"key":"contribution_pct","label":"Beitrag","type":"number","unit":"%","min":0,"max":100,"aria_label":"Beitrag zum Ergebnis in Prozent (§5.5 a) „contribución significativa“)"},{"key":"mechanism","label":"Umweltmechanismus","type":"text","aria_label":"Hauptsächlich betroffener Umweltmechanismus (§5.5 a)"}],"footer":["significant_issues_count"],"note":"a) identificación de las cuestiones significativas basadas en los resultados de la evaluación de la huella de agua por ejemplo: procesos con una contribución significativa al cálculo de las huellas del agua, mecanismos ambientales principalmente afectados, flujos elementales que tienen la mayor contribución a los resultados de la evaluación de la huella de agua; Je Thema eine Zeile; Zwilling des Textfelds significant_issues (iso14046-D-21). Der Beitrag in % ist eine Ingenieurangabe — die Norm nennt keine Schwelle für „significativa“ (iso14046-J-5)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'significant_issues_14046') AND w.code = 'ISO-14046-05' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'significant_issues_count', 'Anzahl signifikanter Themen (aus dem Register)', 'number', NULL, false, '§5.5 a)', 'Plan 3: Ausgabe der Gleichung ISO-14046-05-D1 (count_rows über significant_issues_14046; leeres Register ⇒ 0); Grundlage des STAGED Gate-Vorschlags zu REQ-16 (iso14046-G-11).', 'imported_unverified', 'a) identificación de las cuestiones significativas basadas en los resultados de la evaluación de la huella de agua por ejemplo: procesos con una contribución significativa al cálculo de las huellas del agua, mecanismos ambientales principalmente afectados, flujos elementales que tienen la mayor contribución a los resultados de la evaluación de la huella de agua;', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'significant_issues_count') AND w.code = 'ISO-14046-05' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'third_party_report_items', 'Bericht an Dritte — Aspekte §6.2 a) – g) (Prüfliste, Mehrfachauswahl)', 'json', NULL, false, '§6.2', 'Plan 3: Mehrfachauswahl über die sieben gedruckten Aspekte a) – g) des Berichts an Dritte (S6_2_TP; Unterpunkte in der Tabelle); sichtbar nur bei report_type == third_party (6.2 „Cuando se realiza el informe … a una tercera parte … se debe preparar un informe de tercera parte“); das Einzelfeld third_party_report bleibt (iso14046-D-25); third_party_report_complete_code ist STAGED (iso14046-F-2).', 'imported_unverified', 'Cuando se realiza el informe de los resultados de la evaluación de la huella de agua a una tercera parte (es decir, otras partes interesadas distintas de quien encarga o realiza el estudio), se debe preparar un informe de tercera parte. — El informe de tercera parte constituye un documento de referencia y debe estar disponible para cualquier tercera parte a la cual se informa sobre la evaluación de la huella de agua y los resultados de la huella de agua. El informe de tercera parte debe cubrir los siguientes aspectos:', 'select_many', '{"title":"Inhalte des Berichts an Dritte (§6.2 a) – g))","subtitle":"„El informe de tercera parte debe cubrir los siguientes aspectos:“ — ankreuzen, welche Aspekte der Bericht an Dritte abdeckt (die Unterpunkte 1) … / i) … stehen in der Tabelle S6_2_TP)","note":"El informe de tercera parte constituye un documento de referencia y debe estar disponible para cualquier tercera parte a la cual se informa sobre la evaluación de la huella de agua y los resultados de la huella de agua. El informe de tercera parte debe cubrir los siguientes aspectos: Das Einzelfeld third_party_report (ein Boolean für alle sieben) bleibt bis zur Ratifizierung (iso14046-D-25); REQ-18 liest heute den Boolean in ODER-Form — IF-Guard STAGED (iso14046-G-5); ein Vollständigkeits-Code über die Checkliste ist noch nicht codiert — Entscheidung auf dem Sign-off-Bogen (iso14046-F-2).","groups":[{"label":"§6.2 a) – g)","options":["a) aspectos generales:","b) objetivo del estudio:","c) alcance del estudio:","d) análisis del inventario de la huella de agua:","e) evaluación de la huella de agua, cuando aplique:","f) interpretación:","g) revisión crítica, cuando aplique:"]}]}'::jsonb, NULL, 'report_type == ''third_party''', '[{"value":"a) aspectos generales:","label_de":"a) aspectos generales:","order_index":0},{"value":"b) objetivo del estudio:","label_de":"b) objetivo del estudio:","order_index":1},{"value":"c) alcance del estudio:","label_de":"c) alcance del estudio:","order_index":2},{"value":"d) análisis del inventario de la huella de agua:","label_de":"d) análisis del inventario de la huella de agua:","order_index":3},{"value":"e) evaluación de la huella de agua, cuando aplique:","label_de":"e) evaluación de la huella de agua, cuando aplique:","order_index":4},{"value":"f) interpretación:","label_de":"f) interpretación:","order_index":5},{"value":"g) revisión crítica, cuando aplique:","label_de":"g) revisión crítica, cuando aplique:","order_index":6}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'third_party_report_items') AND w.code = 'ISO-14046-06' AND s.code = 'ISO-14046';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'review_panel', 'Prüfungsausschuss (je Mitglied: Name, Zugehörigkeit, unabhängig, Vorsitz)', 'json', NULL, false, '§7.4, §6.2 g) 1)', 'Plan 3: Zeilen je Ausschussmitglied („un panel de revisión constituido por al menos tres miembros“; 6.2 g) 1) „nombre y afiliación de los revisores“); sichtbar nur bei critical_review_type == panel_review; Anzahl → review_panel_members_calc (ISO-14046-07-D1), unabhängige Vorsitzende → panel_chair_independent (-D2), mindestens drei → panel_min_members_ok (-D3); das Zahlenfeld review_panel_members bleibt (iso14046-D-22).', 'imported_unverified', 'Una revisión crítica se puede realizar como una revisión por las partes interesadas. En este caso, quien encarga el estudio original debería seleccionar un experto externo independiente para presidir un panel de revisión constituido por al menos tres miembros. Con base en el objetivo y el alcance del estudio, el presidente debería seleccionar otros revisores independientes calificados. Este panel puede incluir otras partes interesadas afectadas por las conclusiones extraídas de la evaluación de la huella de agua; tales como agencias gubernamentales, grupos no gubernamentales, competidores e industrias afectadas. — La declaración de revisión y el informe del panel de revisión, así como los comentarios del experto y cualquier respuesta a las recomendaciones hechas por el revisor o el panel deben incluirse en el informe de la evaluación de la huella de agua.', 'register', '{"title":"Prüfungsausschuss (panel de revisión, §7.4)","subtitle":"§7.4 — „un panel de revisión constituido por al menos tres miembros“, Vorsitz durch einen unabhängigen externen Sachverständigen; je Mitglied eine Zeile","add_label":"+ Mitglied","placement":"section","columns":[{"key":"name","label":"Name","type":"text","required":true,"aria_label":"Name des Ausschussmitglieds (§6.2 g) 1) „nombre y afiliación de los revisores“)"},{"key":"affiliation","label":"Zugehörigkeit","type":"text","aria_label":"Zugehörigkeit / Organisation des Mitglieds (§6.2 g) 1)"},{"key":"independent","label":"unabhängig","type":"boolean","aria_label":"Unabhängiger Prüfer (§7.4 „revisores independientes calificados“)"},{"key":"chair","label":"Vorsitz","type":"boolean","aria_label":"Vorsitz des Ausschusses (§7.4 „experto externo independiente para presidir“)"}],"footer":["review_panel_members_calc","panel_chair_independent","panel_min_members_ok"],"note":"Una revisión crítica se puede realizar como una revisión por las partes interesadas. En este caso, quien encarga el estudio original debería seleccionar un experto externo independiente para presidir un panel de revisión constituido por al menos tres miembros. Con base en el objetivo y el alcance del estudio, el presidente debería seleccionar otros revisores independientes calificados. Este panel puede incluir otras partes interesadas afectadas por las conclusiones extraídas de la evaluación de la huella de agua; tales como agencias gubernamentales, grupos no gubernamentales, competidores e industrias afectadas. Je Mitglied eine Zeile; Zwilling des Zahlenfelds review_panel_members (iso14046-D-22). Anzahl → review_panel_members_calc, unabhängige Vorsitzende → panel_chair_independent, „al menos tres miembros“ → panel_min_members_ok (ISO-14046-07-D1 … D3); ein Gate auf mindestens drei Mitglieder ist STAGED (iso14046-G-3 — Modalverb „debería“)."}'::jsonb, NULL, 'critical_review_type == ''panel_review''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'review_panel') AND w.code = 'ISO-14046-07' AND s.code = 'ISO-14046';
